import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { escapeXml, compact, wrap, contributionParagraph, validateFeatured, validateMetadata, cardSvg, readmeBlock, refreshMetadata, iconSvg, DESKTOP_WIDTH } from './render-contribution-cards.mjs';
const base = new URL('../../profile/contributions/',import.meta.url);
const cards=JSON.parse(await readFile(new URL('featured.json',base),'utf8'));
const data=JSON.parse(await readFile(new URL('metadata.json',base),'utf8'));
test('reviewed public inventory and matching cached metadata',()=>{validateFeatured(cards);validateMetadata(data,cards);});
test('compact stars preserve small values',()=>{assert.equal(compact(97),'97');assert.equal(compact(21685),'21.7k');assert.equal(compact(7759),'7.8k');for(const n of [-1,NaN,Infinity,1.2])assert.throws(()=>compact(n));});
test('paragraph normalization preserves sentences, not a PR checklist',()=>{assert.equal(contributionParagraph('One.\n\nTwo.  Three.'),'One. Two. Three.');assert.throws(()=>contributionParagraph(''));assert.throws(()=>contributionParagraph('x'.repeat(361)));});
test('copy wraps without truncation',()=>{assert.deepEqual(wrap('one two three',7),['one two','three']);assert.throws(()=>wrap('averylongword',3));for(const c of cards)assert.equal(wrap(c.contribution,42).join(' '),contributionParagraph(c.contribution));});
test('escapes untrusted text',()=>{assert.equal(escapeXml('<&"'), '&lt;&amp;&quot;');const svg=cardSvg({...cards[0], description:'<script> & "quote"'},data.repositories[cards[0].repo]);assert.ok(!svg.includes('<script>'));assert.ok(svg.includes('&lt;script&gt;'));});
test('auto theme is internal to each image; no page styling or remote artwork',()=>{for(const c of cards)for(const mobile of [false,true]){const s=cardSvg(c,data.repositories[c.repo],'auto',mobile,data.as_of);assert.match(s,/<title id="title">/);assert.match(s,/<desc id="desc">/);assert.match(s,/@media\(prefers-color-scheme:dark\)/);assert.doesNotMatch(s,/<script|<foreignObject|(?:href|src)=["']https?:|onload=/);}});
test('README source selection cannot combine theme and width',()=>{const s=readmeBlock(cards,data);assert.equal((s.match(/<source /g)||[]).length,cards.length);assert.equal((s.match(/media="\(max-width: 520px\)"/g)||[]).length,cards.length);assert.doesNotMatch(s,/prefers-color-scheme/);});
test('README does not force desktop width onto a selected mobile image',()=>{const s=readmeBlock(cards,data);assert.doesNotMatch(s,/<img[^>]*(?:width|height)=/);assert.equal((s.match(/<picture>/g)||[]).length,cards.length);});
test('native image dimensions cap size even if source selection is lost',()=>{for(const c of cards)for(const mobile of [false,true]){const s=cardSvg(c,data.repositories[c.repo],'auto',mobile,data.as_of);const [,w,h]=s.match(/width="(\d+)" height="(\d+)"/);assert.equal(Number(w),mobile?400:DESKTOP_WIDTH);assert.ok(Number(h)<=(mobile?140:100));}});
test('README has no reintroduced filler or link rows',()=>{const s=readmeBlock(cards,data);assert.equal((s.match(/<a href=/g)||[]).length,cards.length);assert.doesNotMatch(s,/<sub>|<br>|Stargazers|My contributions|Stars belong|snapshot:|shields\.io/);assert.ok(s.includes(`stars checked ${data.as_of}`));for(const c of cards)assert.ok(s.includes(`href="https://github.com/${c.repo}"`));});
test('one arrow introduces the complete paragraph',()=>{for(const c of cards)for(const mobile of [false,true]){const s=cardSvg(c,data.repositories[c.repo],'auto',mobile,data.as_of);assert.equal((s.match(/data-contribution-arrow=/g)||[]).length,1);}});
test('verified project icons replace the bookmark glyph; fallback is a monogram',()=>{for(const id of ['codexbar','vscodevim','raycast','flowbite'])assert.match(iconSvg(id,16,14),new RegExp(`data-project-icon="${id}"`));assert.match(iconSvg('edgevec',16,14),/data-project-icon="monogram"/);assert.doesNotMatch(iconSvg('edgevec',16,14),/M2 3h17/);});
test('paths and duplicate ids are rejected',()=>{assert.throws(()=>validateFeatured([{...cards[0],id:'../escape'}]));assert.throws(()=>validateFeatured([cards[0],cards[0]]));assert.throws(()=>validateFeatured([{...cards[0],repo:'x/y?token=secret'}]));});
test('refresh refuses private and mismatched repository responses',async()=>{await assert.rejects(()=>refreshMetadata(cards,data,async()=>({ok:true,json:async()=>({private:true,full_name:cards[0].repo})})),/private/);await assert.rejects(()=>refreshMetadata(cards,data,async()=>({ok:true,json:async()=>({private:false,full_name:'other/repo'})})),/Unexpected/);});
test('rate limits cannot produce fabricated zero counts',async()=>{await assert.rejects(()=>refreshMetadata(cards,data,async()=>({ok:false,status:403})),/HTTP 403/);});
test('refresh copies only allowlisted public metadata',async()=>{const fresh=await refreshMetadata(cards,data,async(url)=>({ok:true,json:async()=>({private:false,full_name:url.replace('https://api.github.com/repos/',''),stargazers_count:123,language:'Swift',secrets:'never copy'})}));validateMetadata(fresh,cards);assert.ok(!JSON.stringify(fresh).includes('secrets'));assert.equal(Object.keys(fresh.repositories).length,5);});
